function el(tag,text,className){const e=document.createElement(tag);if(text)e.textContent=text;if(className)e.className=className;return e;}
function publicLink(url,text){const a=el('a',text);a.href=url;if(!url.startsWith('#')){a.target='_blank';a.rel='noopener noreferrer';}return a;}
function buildPublic(key){const box=el('div',null,key==='kabar'?'news-grid':'public-links');if(key==='kabar'){for(const item of window.BRMP_CONTENT.articles){const card=el('article',null,'news-card');if(item.image){const img=el('img');img.src=item.image;img.alt=item.title;img.className='news-photo';img.loading='lazy';card.append(img);}const date=el('time',item.date);date.dateTime=item.date;card.append(date,el('h3',item.title),el('p',item.body));const a=publicLink(item.url,'Baca selengkapnya ↗');a.className='inline-link';card.append(a);box.append(card);}}else{for(const item of window.BRMP_CONTENT.services.filter(s=>key==='kanal'?s.category==='Publik':s.category!=='Publik')){const a=publicLink(item.url,'');const copy=el('div');copy.append(el('b',item.name),el('small',item.source));a.append(copy,el('span','↗'));box.append(a);}}if(!box.children.length)box.append(el('p','Belum ada konten yang diterbitkan.'));return box;}
(async()=>{try{const response=await fetch('/api/content',{cache:'no-store'});if(!response.ok)throw new Error();window.BRMP_CONTENT=await response.json();const data=window.BRMP_CONTENT;if(data.site){const site=data.site;document.querySelector('#office-address').textContent=site.address;document.querySelector('.location-details h3').textContent=site.name;document.querySelector('#tentang .about-grid>div>p').textContent=site.profile;document.querySelectorAll('a[href^="tel:"]').forEach(a=>{a.href='tel:'+site.phone;(a.querySelector('b')||a).textContent=site.phone;});document.querySelectorAll('a[href^="mailto:"]').forEach(a=>{a.href='mailto:'+site.email;(a.querySelector('b')||a).textContent=site.email;});document.querySelectorAll('a[href^="https://wa.me/"]').forEach(a=>{a.href='https://wa.me/'+site.whatsapp;if(!a.hasAttribute('data-contact-label'))(a.querySelector('b')||a).textContent='+'+site.whatsapp;});const mapQuery=encodeURIComponent(site.address);document.querySelector('#open-map').href='https://www.google.com/maps/search/?api=1&query='+mapQuery;document.querySelector('.map-panel iframe').src='https://www.google.com/maps?q='+mapQuery+'&output=embed';}
const hero=document.querySelector('.feature-photo');const feature=data.articles[0];if(!feature)hero.hidden=true;else{hero.querySelector('h2').textContent=feature.title;hero.querySelector('figcaption span').textContent='KEGIATAN BRMP';hero.querySelector('figcaption p').textContent='Publikasi · '+feature.date;hero.querySelector('figcaption a').href=feature.url;hero.querySelector('img').src=feature.image||'/assets/kegiatan-batu-bara.jpg';hero.querySelector('img').alt=feature.title;}
const need=document.querySelector('#need');need.replaceChildren(new Option('Pilih kebutuhan…',''));for(const service of data.services)need.add(new Option(service.name,service.id));const docs=document.querySelector('#knowledge-list');data.knowledge.forEach(k=>{const d=el('details');d.id='knowledge-'+k.id;d.append(el('summary',k.title),el('p',k.body));docs.append(d);});document.querySelector('.chat-note').textContent=data.chatMode==='ai'?'Asisten AI berdasarkan informasi BRMP. Pertanyaan diproses oleh OpenAI. Jangan kirim data pribadi.':'Asisten informasi terkurasi BRMP. Jangan kirim kata sandi atau data pribadi.';for(const src of ['app.js','portal.js','chat.js'])await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=reject;document.head.append(s);});}catch{const area=document.querySelector('#service-list');area.replaceChildren(el('p','Layanan belum dapat dimuat. Periksa koneksi lalu coba lagi.'));const retry=el('button','Coba lagi','secondary');retry.addEventListener('click',()=>location.reload());area.append(retry);document.querySelector('#chat-launcher').hidden=true;}})();
